with deduped as (select *, row_number() over (partition by order_id, carrier order by shipped_date desc, id) as row_num from shipments qualify row_num = 1) select s.id, s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.status, s.row_num, (select max(x.amount) from payments x where x.order_id = s.order_id) as max_payment_amount from deduped s order by carrier desc nulls first;
